/*!
 * Local-only Valine placeholder.
 * External comment client bundles are intentionally not loaded by Patch.
 */
(function(global){
  function Valine(options){
    options = options || {};
    var el = typeof options.el === "string" ? document.querySelector(options.el) : options.el;
    if (el) {
      el.innerHTML = '<div class="vempty">Valine comments are not bundled in the local-only build.</div>';
    }
  }
  global.Valine = Valine;
})(typeof window !== "undefined" ? window : this);
